import * as THREE from 'three';
import { GLTFLoader } from './vendor/GLTFLoader.js';
import { RoomEnvironment } from './vendor/RoomEnvironment.js';
const $=s=>document.querySelector(s), canvas=$('#scene'), container=$('.experience');
const scene=new THREE.Scene();scene.background=new THREE.Color('#c3b7a3');
const camera=new THREE.PerspectiveCamera(62,1,.04,100);camera.rotation.order='YXZ';
let renderer;try{renderer=new THREE.WebGLRenderer({canvas,antialias:true});}catch(e){$('#loading').innerHTML='<strong>3D graphics unavailable</strong><small>Enable hardware acceleration in your browser, then reload.</small>';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(new RoomEnvironment(),.04).texture;scene.environmentIntensity=.35;pmrem.dispose();
const hemi=new THREE.HemisphereLight(0xffe9cc,0x6b5540,.65);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffdeb0,1.2);sun.position.set(-3,7,5);scene.add(sun);
for(const z of [3,7,12]){const l=new THREE.SpotLight(0xffdeb0,25,8,1.1,.7,1.5);l.position.set(0,2.85,-z);l.target.position.set(0,0,-z);l.castShadow=true;l.shadow.mapSize.set(1024,1024);l.shadow.bias=-.0004;scene.add(l,l.target);}
const interior=[];for(let z of [1.4,3.6,5.8,8,10.3,12.5]){let l=new THREE.PointLight(0xffcd88,19,5,2);l.position.set(0,2.4,-z);scene.add(l);interior.push(l);}
// Blender uses Z up; glTF converts to Y up and negative Z depth.
const stops=[
 {title:'The arrival.',description:'A warm walnut frame and quiet brass lettering welcome you inside.',p:[0,1.75,3.8],t:[0,1.55,-2]},
 {title:'A warm welcome.',description:'The long sightline draws you through the room, from the entrance to the open kitchen.',p:[.66,1.65,-.65],t:[-.15,1.4,-7.5]},
 {title:'Stay a little longer.',description:'Cognac channel seating, cream stone tables and the soft glow of opal globes.',p:[.72,1.65,-4.1],t:[-1.05,1.05,-5.9]},
 {title:'Craft on display.',description:'A walnut and cream counter frames the ingredients, with a working passage to the right.',p:[.68,1.65,-7.85],t:[-.4,1.25,-9.3]},
 {title:'Behind the experience.',description:'Preparation and cold storage lead to the shawarma, griddle, fryer, round cooker and sink.',p:[.42,1.7,-11.9],t:[0,1.42,-13.05]}
];
let model,selected=0,transition=null,touring=false,tourAt=0,cutaway=false,day=false,drag=null,yaw=0,pitch=0,keys=new Set(),ready=false;
const hidden=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function finishMaterials(root){const seen=new Set();root.traverse(o=>{if(!o.isMesh||seen.has(o.material))return;const m=o.material;seen.add(m);const name=m.name.toLowerCase();if(/walnut|cognac|limestone|plaster/.test(name)){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');const im=ctx.createImageData(256,256);let seed=19;for(let y=0;y<256;y++)for(let x=0;x<256;x++){seed=(seed*16807)%2147483647;let n=seed/2147483647;let value=225+n*24;if(name.includes('walnut'))value=140+32*Math.sin(x*.31+Math.sin(y*.035)*1.8)+n*28;else if(name.includes('cognac'))value=185+n*45;else if(name.includes('limestone'))value=209+Math.sin(x*.06+Math.sin(y*.04))*12+n*16;let k=(y*256+x)*4;im.data[k]=im.data[k+1]=im.data[k+2]=value;im.data[k+3]=255;}ctx.putImageData(im,0,0);const tx=new THREE.CanvasTexture(c);tx.colorSpace=THREE.SRGBColorSpace;tx.wrapS=tx.wrapT=THREE.RepeatWrapping;tx.anisotropy=4;m.map=tx;m.bumpMap=tx;m.bumpScale=name.includes('cognac')?.003:.008;m.needsUpdate=true;}if(name.includes('brass'))m.envMapIntensity=1.4;});}
function syncAngles(){const e=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');yaw=e.y;pitch=e.x;}
function moveTo(p,t,duration=1800){const dest=new THREE.Vector3(...p),dummy=new THREE.PerspectiveCamera();dummy.position.copy(dest);dummy.lookAt(...t);transition={start:performance.now(),duration:reduced?0:duration,from:camera.position.clone(),to:dest,q0:camera.quaternion.clone(),q1:dummy.quaternion.clone()};}
function stopTour(){touring=false;$('#tour').textContent='▶ Guided tour';}
function setCut(on){cutaway=on;hidden.forEach(o=>o.visible=!on);$('#cut').setAttribute('aria-pressed',String(on));}
function go(i,auto=false){if(!ready)return;if(!auto)stopTour();setCut(false);selected=i;const s=stops[i];moveTo(s.p,s.t);$('#title').textContent=s.title;$('#description').textContent=s.description;$('#number').textContent=`0${i+1} / 05`;$('.stops').querySelectorAll('button').forEach((b,n)=>{b.classList.toggle('active',n===i);b.setAttribute('aria-current',n===i?'step':'false');});$('#marker').style.bottom=[2,9,36,65,88][i]+'%';tourAt=performance.now();}
camera.position.set(...stops[0].p);camera.lookAt(...stops[0].t);syncAngles();
new GLTFLoader().load('./assets/heritage-a.glb',g=>{model=g.scene;finishMaterials(model);scene.add(model);model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;if(o.name.startsWith('Ceiling')||o.name.startsWith('Wall_shell')||o.name.startsWith('Rear_wall'))hidden.push(o);if(o.material){o.material.side=THREE.DoubleSide;}}});ready=true;$('#loading').style.display='none';go(0);window.walkthrough={scene,camera,model,go,getState:()=>({selected,cutaway,touring,ready,meshes:renderer.info.render.calls})};},undefined,e=>{$('#loading').innerHTML='<strong>The model could not load</strong><small>Please reload this page to try again.</small>';console.error(e);});
document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>go(Number(b.dataset.stop)));
$('#reset').onclick=()=>go(selected);
$('#tour').onclick=()=>{if(touring){stopTour();return;}touring=true;$('#tour').textContent='Ⅱ Pause tour';go(0,true);};
$('#cut').onclick=()=>{if(!ready)return;stopTour();setCut(!cutaway);if(cutaway){moveTo([9,12,6],[0,0,-6.5],2000);$('#title').textContent='The complete picture.';$('#description').textContent='An open-roof view of the 10 × 44-foot concept. Select any section to step back inside.';}else go(selected);};
$('#light').onclick=()=>{day=!day;$('#light').setAttribute('aria-pressed',String(day));$('#light').textContent=day?'☾ Evening':'☀ Daylight';hemi.intensity=day?1.4:.65;sun.intensity=day?2.5:1.2;interior.forEach(l=>l.intensity=day?8:19);renderer.toneMappingExposure=day?1.1:.95;scene.background.set(day?'#dcd4c5':'#c3b7a3');};
$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await container.requestFullscreen();}catch{ $('#full').textContent='Unavailable';}};
function dialog(id){$(id).showModal();stopTour();keys.clear();}$('#about').onclick=()=>dialog('#notes');$('#reference').onclick=()=>dialog('#ref');document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
canvas.addEventListener('pointerdown',e=>{if(!ready)return;stopTour();transition=null;syncAngles();drag={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.focus();});
canvas.addEventListener('pointermove',e=>{if(!drag)return;yaw-=(e.clientX-drag.x)*.003;pitch=Math.max(-1.2,Math.min(1.2,pitch-(e.clientY-drag.y)*.003));camera.rotation.set(pitch,yaw,0,'YXZ');drag={x:e.clientX,y:e.clientY};});
canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);
const moveKeys=['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'];window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if(moveKeys.includes(k)){e.preventDefault();keys.add(k);stopTour();transition=null;}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();drag=null;});
for(const [id,key] of [['forward','w'],['back','s']]){$('#'+id).addEventListener('pointerdown',e=>{stopTour();transition=null;keys.add(key);e.target.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('#'+id).addEventListener(event,()=>keys.delete(key));}
function walk(dt){if(!keys.size||cutaway||!ready)return;let f=Number(keys.has('w')||keys.has('arrowup'))-Number(keys.has('s')||keys.has('arrowdown')),r=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'));let v=new THREE.Vector3(r,0,-f);if(v.lengthSq())v.normalize().applyAxisAngle(new THREE.Vector3(0,1,0),camera.rotation.y).multiplyScalar(dt*1.35);const next=camera.position.clone().add(v);next.z=THREE.MathUtils.clamp(next.z,-12.13,4);next.y=1.65;let low=-1.2,high=1.2;if(next.z<-.2&&next.z>-8.5){low=.28;high=1.04;}if(next.z<=-8.5&&next.z>=-9.65){low=.86;high=1.20;}if(next.z<-9.65){low=-.60;high=.62;}next.x=THREE.MathUtils.clamp(next.x,low,high);camera.position.copy(next);$('#marker').style.bottom=THREE.MathUtils.clamp(-next.z/13.4*100,2,94)+'%';}
const resize=()=>{const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(container);resize();
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.04);last=now;if(transition){let a=transition.duration?Math.min(1,(now-transition.start)/transition.duration):1;a=a*a*(3-2*a);camera.position.lerpVectors(transition.from,transition.to,a);camera.quaternion.slerpQuaternions(transition.q0,transition.q1,a);if(a>=1){transition=null;syncAngles();}}walk(dt);if(touring&&now-tourAt>6500){if(selected===4)stopTour();else go(selected+1,true);}renderer.render(scene,camera);}requestAnimationFrame(animate);


